// JavaScript port of the Python scoring/explanation module (dawawala_risk).
//
// ONLY the mock backend uses this. The real engine runs on the server
// (SRS FR-11, FR-13). A parity test (engine.test.js) compares this file with
// output generated by the Python module, so the demo shows what the real
// backend will return. Keep CONFIG in sync with scoring_config.json.

export const CONFIG = {
  scoreMax: 100,
  severityPoints: { minor: 10, moderate: 30, major: 50, contraindicated: 70 },
  duplicatePoints: 30,
  therapeuticDuplicationPoints: 15,
  cascadePoints: 25,
  patientFactorPoints: 5,
  patientFactorMax: 15,
  bandThresholds: [25, 50, 75],
  categoryOrder: ["contraindication", "interaction", "cascade", "duplicate"],
  explanationMaxWords: 150,
  kbStaleDays: 180,
};

export const BAND_NAMES = ["Low", "Moderate", "High", "Critical"];
export const FACTOR_ORDER = ["age_65_plus", "kidney_impaired", "liver_impaired"];
export const FACTOR_LABELS = {
  age_65_plus: "age 65 or over",
  kidney_impaired: "impaired kidney function",
  liver_impaired: "impaired liver function",
};

export const DISCLAIMER =
  "Decision support only. This is not medical advice. " +
  "Discuss these results with your doctor or pharmacist.";

const T = {
  ADVICE: "Please discuss this with your doctor or pharmacist.",
  TRACE: "Source: rule {rule_id}, knowledge base version {kb_version}.",
  FACTOR_LINE: "Your answer about {factors} raised its priority score.",
  INTERACTION_FOUND: "We found a possible interaction between {medicines}.",
  INTERACTION_SEVERITY: {
    minor: "The knowledge base rates it as minor. The effect is usually small.",
    moderate:
      "The knowledge base rates it as moderate. It may change how well a " +
      "medicine works, or add side effects.",
    major:
      "The knowledge base rates it as major. It may cause serious side " +
      "effects or keep a medicine from working well.",
    contraindicated:
      "The knowledge base rates it as contraindicated. These medicines are " +
      "not usually meant to be used together.",
  },
  INTERACTION_SEVERITY_DEFAULT:
    "The knowledge base rates it as {severity}. It may affect how the " +
    "medicines work.",
  CONTRA_FOUND: "We found a possible concern about {medicines}.",
  CONTRA_WITH_CONDITION:
    "The knowledge base says it may not be suitable for people with " +
    "{condition}.",
  CONTRA_NO_CONDITION: "The knowledge base says it may not be suitable for you.",
  CONTRA_SEVERITY: {
    minor: "The concern is rated as minor. It may add mild side effects.",
    moderate:
      "The concern is rated as moderate. It may add side effects or make " +
      "the medicine work less well.",
    major: "The concern is rated as major. It may raise the risk of harm.",
    contraindicated:
      "The concern is rated as contraindicated. This means the medicine is " +
      "not usually meant to be used in this case.",
  },
  CONTRA_SEVERITY_DEFAULT: "The concern is rated as {severity}.",
  DUPLICATE_EXACT:
    "We found {medicines} more than once in your list, possibly under " +
    "different brand names. Taking the same medicine twice may give you too " +
    "much of it. That can raise the chance of side effects.",
  DUPLICATE_THERAPEUTIC:
    "We found two medicines, {medicines}, that belong to the same drug " +
    "class. Medicines in one class often do a similar job. Using both may " +
    "give more of the same effect than intended. This is only a possible " +
    "duplication.",
  CASCADE_FOUND: "We found a possible prescribing cascade.",
  CASCADE_DETAIL:
    "{trigger} may cause {symptom}. {downstream} is sometimes used to treat " +
    "that problem.",
  CASCADE_FALLBACK: "The medicines involved are {medicines}.",
  CASCADE_WHY:
    "A side effect can be mistaken for a new health problem. This may not " +
    "apply to you. It is not a diagnosis.",
};

const fill = (text, values) =>
  text.replace(/\{(\w+)\}/g, (_, key) => values[key]);

// SAF-06 / SAF-03: wording that must never appear in user-facing text.
const FORBIDDEN = new RegExp(
  "\\b(?:" +
    "(?:stop|start|begin|quit|discontinue|cease|skip|avoid|" +
    "increase|decrease|reduce|lower|double|halve|adjust|change|switch|" +
    "swap|replace)\\s+" +
    "(?:(?:to|your|the|this|that|these|those|its|their|a|an|any|all|each|" +
    "another|other)\\s+){0,2}" +
    "(?:taking|using|it|them|dose|doses|dosage|medicine|medicines|" +
    "medication|medications|drug|drugs|tablet|tablets|pill|pills)" +
    "|do\\s+not\\s+(?:take|use)|don'?t\\s+(?:take|use)" +
    "|you\\s+(?:should|must|need\\s+to)\\s+(?:take|use|stop|start)" +
    "|safe(?:ly)?" +
    ")\\b",
  "gi"
);

export function forbiddenPhrases(text) {
  return [...text.matchAll(FORBIDDEN)].map((m) => m[0]);
}

export const wordCount = (text) =>
  text.split(/\s+/).filter(Boolean).length;

export function joinNames(names) {
  const items = [...names];
  if (items.length <= 1) return items.join("");
  return items.slice(0, -1).join(", ") + " and " + items[items.length - 1];
}

const capitalize = (s) => s.charAt(0).toUpperCase() + s.slice(1).toLowerCase();

// ---- input normalisation (mirrors WarningInput / PatientFactors) ----------

export function normalizePatient(data) {
  const d = data || {};
  const pick = (value, allowed, name) => {
    const v = String(value ?? "unknown").trim().toLowerCase();
    if (!allowed.includes(v)) throw new Error(`invalid ${name}: ${value}`);
    return v;
  };
  return {
    age_range: pick(d.age_range, ["under_18", "18_64", "65_plus", "unknown"], "age_range"),
    kidney_function: pick(d.kidney_function, ["normal", "impaired", "unknown"], "kidney_function"),
    liver_function: pick(d.liver_function, ["normal", "impaired", "unknown"], "liver_function"),
  };
}

function activeFactors(patient) {
  const active = new Set();
  if (patient.age_range === "65_plus") active.add("age_65_plus");
  if (patient.kidney_function === "impaired") active.add("kidney_impaired");
  if (patient.liver_function === "impaired") active.add("liver_impaired");
  return active;
}

export function normalizeWarning(data) {
  let category = String(data.category).trim().toLowerCase();
  if (category === "ddi") category = "interaction";
  if (!CONFIG.categoryOrder.includes(category)) {
    throw new Error(`unknown warning category: ${data.category}`);
  }
  const medicines = (data.medicines || [])
    .map((m) => String(m).trim())
    .filter(Boolean);
  if (!medicines.length) throw new Error("a warning must name a medicine");
  if (!String(data.rule_id || "").trim()) throw new Error("missing rule_id");
  if (!String(data.kb_version || "").trim()) throw new Error("missing kb_version");
  const relevant = [...(data.relevant_factors || [])];
  if (relevant.some((f) => !FACTOR_ORDER.includes(f))) {
    throw new Error("unknown relevant factor");
  }
  let severity = data.severity ? String(data.severity).trim().toLowerCase() : null;
  if (["interaction", "contraindication"].includes(category) && !severity) {
    throw new Error(`${category} warnings require a severity`);
  }
  let duplicateKind = String(data.duplicate_kind || "exact").trim().toLowerCase();
  if (category === "duplicate" && !["exact", "therapeutic"].includes(duplicateKind)) {
    throw new Error(`unknown duplicate_kind: ${duplicateKind}`);
  }
  return {
    category,
    medicines,
    rule_id: data.rule_id,
    kb_version: data.kb_version,
    severity,
    relevant_factors: relevant,
    duplicate_kind: duplicateKind,
    description: data.description || "",
    condition: data.condition || "",
    trigger: data.trigger || "",
    symptom_pattern: data.symptom_pattern || "",
    downstream: data.downstream || "",
  };
}

// ---- scoring (FR-11) -------------------------------------------------------

export function bandFor(score) {
  return BAND_NAMES[CONFIG.bandThresholds.filter((b) => score >= b).length];
}

function baseFactor(w) {
  if (w.category === "interaction" || w.category === "contraindication") {
    const points = CONFIG.severityPoints[w.severity];
    if (points === undefined) throw new Error(`unknown severity ${w.severity}`);
    return {
      code: `severity_${w.severity}`,
      label: `Rule severity (${w.category}): ${capitalize(w.severity)}`,
      points,
    };
  }
  if (w.category === "duplicate") {
    if (w.duplicate_kind === "therapeutic") {
      return {
        code: "therapeutic_duplication",
        label: "Possible therapeutic duplication (same drug class)",
        points: CONFIG.therapeuticDuplicationPoints,
      };
    }
    return {
      code: "duplicate_medication",
      label: "Duplicate medication (same medicine entered more than once)",
      points: CONFIG.duplicatePoints,
    };
  }
  return {
    code: "cascade_pattern",
    label: "Possible prescribing-cascade pattern",
    points: CONFIG.cascadePoints,
  };
}

function patientFactorItems(w, patient) {
  const active = activeFactors(patient);
  let remaining = CONFIG.patientFactorMax;
  const out = [];
  for (const code of FACTOR_ORDER) {
    if (!w.relevant_factors.includes(code) || !active.has(code)) continue;
    const points = Math.min(CONFIG.patientFactorPoints, remaining);
    if (points <= 0) break;
    out.push({
      code: `patient_${code}`,
      label: `Patient factor: ${FACTOR_LABELS[code]}`,
      points,
    });
    remaining -= points;
  }
  return out;
}

export function scoreWarning(w, patient) {
  const factors = [baseFactor(w), ...patientFactorItems(w, patient)];
  const rawTotal = factors.reduce((sum, f) => sum + f.points, 0);
  const score = Math.min(rawTotal, CONFIG.scoreMax);
  return {
    warning: w,
    score,
    raw_total: rawTotal,
    capped: rawTotal > CONFIG.scoreMax,
    band: bandFor(score),
    factors,
  };
}

// ---- explanations (FR-13) --------------------------------------------------

function firstSentences(text, budget) {
  const sentences = text.trim().split(/(?<=[.!?])\s+/);
  const kept = [];
  let used = 0;
  for (const s of sentences) {
    const n = wordCount(s);
    if (used + n > budget) break;
    kept.push(s);
    used += n;
  }
  return kept.join(" ");
}

function coreSentences(sw) {
  const w = sw.warning;
  const meds = joinNames(w.medicines);
  const sev = w.severity || "";
  if (w.category === "interaction") {
    const why =
      T.INTERACTION_SEVERITY[sev] ??
      fill(T.INTERACTION_SEVERITY_DEFAULT, { severity: sev });
    return [fill(T.INTERACTION_FOUND, { medicines: meds }), why];
  }
  if (w.category === "contraindication") {
    const detail = w.condition
      ? fill(T.CONTRA_WITH_CONDITION, { condition: w.condition })
      : T.CONTRA_NO_CONDITION;
    const why =
      T.CONTRA_SEVERITY[sev] ?? fill(T.CONTRA_SEVERITY_DEFAULT, { severity: sev });
    return [fill(T.CONTRA_FOUND, { medicines: meds }), detail, why];
  }
  if (w.category === "duplicate") {
    const text =
      w.duplicate_kind === "therapeutic" ? T.DUPLICATE_THERAPEUTIC : T.DUPLICATE_EXACT;
    return [fill(text, { medicines: meds })];
  }
  const detail =
    w.trigger && w.symptom_pattern && w.downstream
      ? fill(T.CASCADE_DETAIL, {
          trigger: w.trigger,
          symptom: w.symptom_pattern,
          downstream: w.downstream,
        })
      : fill(T.CASCADE_FALLBACK, { medicines: meds });
  return [T.CASCADE_FOUND, detail, T.CASCADE_WHY];
}

function tailSentences(sw) {
  const w = sw.warning;
  const tail = [];
  const applied = sw.factors.filter((f) => f.code.startsWith("patient_"));
  if (applied.length) {
    const names = applied.map((f) => FACTOR_LABELS[f.code.slice("patient_".length)]);
    tail.push(fill(T.FACTOR_LINE, { factors: joinNames(names) }));
  }
  tail.push(fill(T.TRACE, { rule_id: w.rule_id, kb_version: w.kb_version }));
  tail.push(T.ADVICE);
  return tail;
}

export function buildExplanation(sw) {
  const core = coreSentences(sw).join(" ");
  const tail = tailSentences(sw).join(" ");
  const description = sw.warning.description.trim();
  let middle = "";
  if (description) {
    const budget = CONFIG.explanationMaxWords - wordCount(core + " " + tail);
    const candidate = firstSentences(description, budget);
    if (candidate && !forbiddenPhrases(candidate).length) middle = candidate;
  }
  const text = [core, middle, tail].filter(Boolean).join(" ");
  if (wordCount(text) > CONFIG.explanationMaxWords) {
    throw new Error(`explanation exceeds ${CONFIG.explanationMaxWords} words`);
  }
  const leftover = forbiddenPhrases(text);
  if (leftover.length) {
    throw new Error("explanation contains forbidden wording: " + leftover.join(", "));
  }
  return text;
}

// ---- ranking and entry points ---------------------------------------------

const sortName = (w) =>
  w.medicines
    .map((m) => m.toLowerCase())
    .sort()
    .join(" + ");

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0);

export function rankWarnings(scored) {
  return [...scored].sort(
    (a, b) =>
      b.score - a.score ||
      CONFIG.categoryOrder.indexOf(a.warning.category) -
        CONFIG.categoryOrder.indexOf(b.warning.category) ||
      cmp(sortName(a.warning), sortName(b.warning)) ||
      cmp(a.warning.rule_id, b.warning.rule_id)
  );
}

export function toApiWarning(sw) {
  const w = sw.warning;
  return {
    category: w.category,
    medicines: w.medicines,
    rule_id: w.rule_id,
    kb_version: w.kb_version,
    severity: w.severity,
    score: sw.score,
    raw_total: sw.raw_total,
    capped: sw.capped,
    band: sw.band,
    factors: sw.factors,
    explanation: sw.explanation,
  };
}

export function bandCounts(warnings) {
  const counts = Object.fromEntries(BAND_NAMES.map((b) => [b, 0]));
  for (const w of warnings) counts[w.band] += 1;
  return counts;
}

/** Same contract as the backend's analyse_payload(). */
export function analysePayload(payload) {
  const patient = normalizePatient(payload.patient_factors);
  const scored = (payload.warnings || []).map((raw) => {
    const sw = scoreWarning(normalizeWarning(raw), patient);
    sw.explanation = buildExplanation(sw);
    return sw;
  });
  const warnings = rankWarnings(scored).map(toApiWarning);
  return { warnings, band_counts: bandCounts(warnings) };
}

/** SAF-07: notice when the knowledge base is older than KB_STALE_DAYS. */
export function kbNotice(kbUpdated, today = new Date()) {
  const days = Math.floor((today - new Date(kbUpdated)) / 86400000);
  if (days > CONFIG.kbStaleDays) {
    return (
      `The knowledge base was last updated more than ${CONFIG.kbStaleDays} ` +
      "days ago. Results may be out of date."
    );
  }
  return null;
}
